import time
import random

def create_retry_fetcher(max_retries=3, base_delay=1000, max_delay=30000, backoff_factor=2, retryable_statuses=None):
    if retryable_statuses is None:
        retryable_statuses = {500, 502, 503, 504}

    def calculate_delay(attempt):
        delay = base_delay * (backoff_factor ** attempt)
        delay = min(delay, max_delay)
        return delay

    def fetch_with_retry(fetch_fn, on_retry=None):
        last_error = None

        for attempt in range(max_retries + 1):
            try:
                result = fetch_fn()
                status = result.get('status', 200)

                if status >= 400:
                    if status not in retryable_statuses:
                        raise Exception(f'Non-retryable error: {status}')
                    if attempt < max_retries:
                        delay = calculate_delay(attempt)
                        jittered = random.random() * delay
                        if on_retry:
                            on_retry(attempt + 1, jittered, f'Status {status}')
                        time.sleep(jittered / 1000)
                        continue
                    raise Exception(f'Max retries exceeded: {status}')

                return result
            except Exception as e:
                last_error = e
                if attempt < max_retries:
                    delay = calculate_delay(attempt)
                    jittered = random.random() * delay
                    if on_retry:
                        on_retry(attempt + 1, jittered, str(e))
                    time.sleep(jittered / 1000)

        raise last_error

    return {
        'fetch': fetch_with_retry,
        'calculate_delay': calculate_delay
    }

