function createRetryFetcher(options = {}) {
  const {
    maxRetries = 3,
    baseDelay = 1000,
    maxDelay = 30000,
    backoffFactor = 2,
    retryableStatuses = [500, 502, 503, 504],
    onRetry = () => {}
  } = options;

  function calculateDelay(attempt) {
    return Math.min(baseDelay * Math.pow(backoffFactor, attempt), maxDelay);
  }

  async function fetchWithRetry(fetchFn) {
    let lastError;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        const response = await fetchFn();

        if (response.status >= 400) {
          if (!retryableStatuses.includes(response.status)) {
            throw new Error(`Non-retryable error: ${response.status}`);
          }
          throw new Error(`Retryable error: ${response.status}`);
        }

        return response;
      } catch (error) {
        lastError = error;

        if (attempt < maxRetries && !error.message.startsWith('Non-retryable')) {
          const delay = calculateDelay(attempt);
          const jittered = Math.random() * delay;
          onRetry(attempt + 1, jittered, error);
          await new Promise(r => setTimeout(r, jittered));
        } else if (error.message.startsWith('Non-retryable')) {
          throw error;
        }
      }
    }

    throw lastError;
  }

  return { fetch: fetchWithRetry, calculateDelay };
}
